"""Corpus of GENUINE Abaqus decks (real-world `.inp` files) for testing the converter.

These are authentic Abaqus inputs - Abaqus/CAE exports (*Part/*Instance/*Assembly),
user-element/UMAT/VUMAT decks, cohesive-zone, explicit-dynamics, coupled
temperature-displacement, piezoelectric/acoustic, mesh-generation cards
(*NGEN/*NFILL/*NCOPY/*ELGEN), named BCs, *Parameter (incl. arithmetic expressions), etc.
- i.e. files that do NOT run in CalculiX directly, so they exercise the actual
conversion. (CalculiX-native decks are deliberately excluded.) Files are NOT committed
(licenses vary - see each entry's `license`; many are "see source repo"); run
`python corpus/fetch.py` to download into corpus/files/ (gitignored), then
`python tests/test_corpus.py`.

1022 decks from ~179 public GitHub repositories; 385 expected to solve in
CalculiX 2.22. Every deck converts cleanly (zero dangling references); the 636
non-solving decks use features ccx cannot run - UMAT/VUMAT user materials, *USER ELEMENT
(UEL), cohesive elements, explicit dynamics, piezoelectric/acoustic coupling, connectors,
other user subroutines - or are CAE part fragments / incomplete source decks. Each was
verified to fail no worse than the original unconverted deck.

This corpus was assembled in waves, the later ones by fanning out parallel discovery
agents across many engineering domains (composites, geotech, biomechanics,
fracture/fatigue, metal forming, thermal/AM, crystal plasticity, acoustics/piezo, civil,
lattices, RVE/homogenization, vibration, FEA-tool test-suites, textbook companions), then
bulk-downloading and running every deck through convert -> referential-integrity check
-> CalculiX. Decks are content-deduplicated (so a byte-identical fixture shared across
repos appears once). That stress test plus adversarial code review drove real converter
fixes - see docs/testing.md.
"""

